const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/plain-console.cjs');
test('ANSI sequences removed without erasing ordinary text', () => {
  for (const [text,expected] of [
    ['\x1b[31mred\x1b[0m','red'],
    ['\x1b[1;32mgreen\x1b[0m','green'],
    ['\x1b[2K\x1b[3GReady','Ready'],
    ['  [note]\t星\n','  [note]\t星\n'], ['','']
  ]) assert.equal(app.plainConsole(text),expected);
});
test('OSC hyperlinks retain labels with each documented terminator', () => {
  for (const end of ['\x07', '\x1b\\', '\x9c']) {
    const text = `\x1b]8;;https://example.com${end}label\x1b]8;;${end}`;
    assert.equal(app.plainConsole(text), 'label');
  }
});

